mapper.select:
SELECT field_id, field_file_id, field_name, field_create_time, field_uploader_id,
       field_delete_flag, field_order, field_model_name, field_model_id, field_key
FROM admin_attachment_main WHERE field_id = #{fieldId}

SELECT m.field_id, m.field_file_id, m.field_name, m.field_create_time, m.field_uploader_id,
       u.field_name AS uploader_name,
       m.field_delete_flag, m.field_order, m.field_model_name, m.field_model_id, m.field_key,
       f.field_file_type, f.field_file_size, f.field_file_path
FROM admin_attachment_main m
LEFT JOIN admin_attachment_file f ON m.field_file_id = f.field_id
LEFT JOIN admin_org_user u ON m.field_uploader_id = u.field_id
 WHERE ${whereSql} 
 ${orderBySql} 
 LIMIT #{pageSize} OFFSET #{offset}

