UPDATE admin_attachment_main
SET field_delete_flag = #{fieldDeleteFlag}
WHERE field_id = #{fieldId}

UPDATE admin_attachment_main
SET field_order = #{fieldOrder}
WHERE field_id = #{fieldId}

mapper.select:
SELECT field_id, field_file_id, field_name, field_create_time, field_uploader_id,
       field_delete_flag, field_order, field_model_name, field_model_id, field_key
FROM admin_attachment_main
WHERE field_delete_flag = 0

    AND field_model_name = #{fieldModelName}


    AND field_model_id = #{fieldModelId}


    AND field_key = #{fieldKey}

ORDER BY field_order ASC
